//! WebP tests: VP8L lossless (byte-exact) and VP8 lossy (PIL/libwebp tolerance).
//!
//! The simple-code VP8L fixtures are generated by `tests/fixtures/generate_webp.py` and
//! validated with PIL/libwebp; their expected ARGB->RGBA output is stored as `.rgba` raw
//! bytes so the Rust decoder is checked byte-for-byte against an independent decoder.
//!
//! The VP8 lossy fixtures (`photo_lossy_q75/q90`, `photo_1024x768_lossy`) are real
//! PIL/libwebp encodings; their `.rgba` files are PIL decodes (independent oracle) and the
//! lossy tests compare within a tolerance instead of byte-for-byte (the in-tree decoder is
//! a from-scratch VP8 port, not libwebp: chroma upsampling/loop-filter rounding can differ
//! by a few units).

use std::path::Path;

use image::{ImageError, ImageFormat, decode, detect_format};

fn fixture(relative: &str) -> Vec<u8> {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/webp")
        .join(relative);
    std::fs::read(&path).unwrap_or_else(|error| panic!("fixture {}: {error}", path.display()))
}

#[test]
fn detects_webp_container() {
    assert_eq!(
        detect_format(&fixture("v8l_two_color.webp")),
        ImageFormat::WebP
    );
}

#[test]
fn decodes_vp8l_two_colour_fixture_exactly() {
    let image = decode(&fixture("v8l_two_color.webp")).expect("VP8L");
    assert_eq!(image.dimensions(), (8, 8));
    assert_eq!(image.data, fixture("v8l_two_color.rgba"));
    assert_eq!(image.pixel(0, 0), Some([255, 0, 0, 255]));
    assert_eq!(image.pixel(7, 7), Some([0, 0, 255, 255]));
}

#[test]
fn decodes_vp8l_alpha_fixture_exactly() {
    let image = decode(&fixture("v8l_alpha.webp")).expect("VP8L alpha");
    assert_eq!(image.dimensions(), (8, 8));
    assert_eq!(image.data, fixture("v8l_alpha.rgba"));
    assert_eq!(image.pixel(0, 0), Some([255, 0, 0, 255]));
    assert_eq!(image.pixel(7, 7), Some([0, 0, 255, 0]), "transparent half");
}

#[test]
fn decodes_vp8l_colour_indexing_fixture_exactly() {
    // PIL/libwebp encodes a solid colour with the colour-indexing transform.
    let image = decode(&fixture("palette_transform.webp")).expect("palette transform");
    assert_eq!(image.dimensions(), (16, 16));
    assert_eq!(image.data, fixture("palette_transform.rgba"));
}

#[test]
fn decodes_real_pil_lossless_photos_exactly() {
    // Real libwebp lossless encodings: predictor/colour transforms, palette and alpha.
    for (name, width, height) in [
        ("photo_transforms", 64u32, 48u32),
        ("palette_real", 32, 24),
        ("alpha_real", 40, 32),
    ] {
        let image = decode(&fixture(&format!("{name}.webp")))
            .unwrap_or_else(|error| panic!("{name}: {error:?}"));
        assert_eq!(image.dimensions(), (width, height), "{name}");
        let expected = fixture(&format!("{name}.rgba"));
        assert_eq!(image.data.len(), expected.len(), "{name}");
        assert_eq!(
            image.data, expected,
            "{name}: pixels must match PIL exactly"
        );
    }
}

#[test]
fn decodes_real_pil_lossy_webp_within_tolerance() {
    // PIL/libwebp q75 and q90 encodings of the same 64x48 synthetic photo. The decoder
    // is a from-scratch VP8 keyframe port: pixels are compared with the PIL RGBA oracle
    // under a documented tolerance (per-channel max and mean absolute error).
    for (name, max_tolerance) in [("photo_lossy_q75", 12), ("photo_lossy_q90", 8)] {
        let image = decode(&fixture(&format!("{name}.webp")))
            .unwrap_or_else(|error| panic!("{name}: {error:?}"));
        assert_eq!(image.dimensions(), (64, 48), "{name}");
        let oracle = fixture(&format!("{name}.rgba"));
        assert_eq!(image.data.len(), oracle.len(), "{name}");
        let (max, mean) = compare_rgba(&image.data, &oracle);
        assert!(
            max <= max_tolerance,
            "{name}: max channel error {max} exceeds {max_tolerance}"
        );
        assert!(
            mean < 1.0,
            "{name}: mean channel error {mean:.3} exceeds 1.0"
        );
        assert!(
            image
                .data
                .as_chunks::<4>()
                .0
                .iter()
                .all(|pixel| pixel[3] == 255),
            "{name}: lossy WebP has no alpha, pixels must be opaque"
        );
    }
}

#[test]
fn decodes_large_lossy_webp_and_scaled_path() {
    let bytes = fixture("photo_1024x768_lossy.webp");
    let image = decode(&bytes).expect("1024x768 VP8 keyframe");
    assert_eq!(image.dimensions(), (1024, 768));
    let oracle = fixture("photo_1024x768_lossy.rgba");
    assert_eq!(oracle.len(), 1024 * 768 * 4);
    let (max, mean) = compare_rgba(&image.data, &oracle);
    assert!(max <= 12, "1024x768: max channel error {max}");
    assert!(mean < 1.0, "1024x768: mean channel error {mean:.3}");

    // decode_scaled uses nearest row/column subsampling after the full decode:
    // output (ox, oy) comes from source (ox * 4, oy * 4) for a 1024px -> 256px scale.
    let scaled = image::decode_scaled(&bytes, 256).expect("scaled 1024x768");
    assert_eq!(scaled.dimensions(), (256, 192));
    let mut max = 0i32;
    for oy in 0..192usize {
        for ox in 0..256usize {
            let source = ((oy * 4) * 1024 + ox * 4) * 4;
            let pixel = &scaled.data[(oy * 256 + ox) * 4..(oy * 256 + ox) * 4 + 4];
            for channel in 0..3 {
                let delta = (i32::from(pixel[channel]) - i32::from(oracle[source + channel])).abs();
                max = max.max(delta);
            }
        }
    }
    assert!(max <= 12, "scaled 256px: max channel error {max}");

    // Deterministic: decoding the same bytes twice yields identical pixels.
    let again = decode(&bytes).expect("second decode");
    assert_eq!(
        image.data, again.data,
        "VP8 lossy decode must be deterministic"
    );
}

#[test]
fn decodes_small_lossy_solid_fixture() {
    // 16x16 solid RGB(30, 160, 90) encoded by PIL at quality 80: lossy, so the
    // reconstructed pixels are close to (but not exactly) the source colour.
    let image = decode(&fixture("lossy.webp")).expect("16x16 VP8 keyframe");
    assert_eq!(image.dimensions(), (16, 16));
    for pixel in image.data.as_chunks::<4>().0 {
        for (channel, expected) in [(0i32, 30i32), (1, 160), (2, 90)] {
            let delta = (i32::from(pixel[channel as usize]) - expected).abs();
            assert!(delta <= 16, "channel {channel}: {pixel:?} vs {expected}");
        }
        assert_eq!(pixel[3], 255);
    }
}

#[test]
fn parses_real_pil_lossy_webp_keyframe_headers() {
    // The public header parser stays useful for tooling: dimensions/version/partition
    // size are validated before decoding, and `decode` now returns the pixels.
    for (name, width, height) in [
        ("photo_lossy_q75", 64u32, 48u32),
        ("photo_lossy_q90", 64, 48),
        ("photo_1024x768_lossy", 1024, 768),
    ] {
        let bytes = fixture(&format!("{name}.webp"));
        let info = image::vp8::lossy_info(&bytes, &image::PngLimits::default())
            .unwrap_or_else(|error| panic!("{name}: {error:?}"));
        assert_eq!((info.width, info.height), (width, height), "{name}");
        assert!(info.version <= 3, "{name}");
        assert!(info.first_partition_size > 0, "{name}");
        let decoded = decode(&bytes).unwrap_or_else(|error| panic!("{name}: {error:?}"));
        assert_eq!(decoded.dimensions(), (width, height), "{name}");
    }
}

#[test]
fn lossy_vp8_dimension_caps_are_enforced() {
    let limits = image::PngLimits {
        max_dimension: 32,
        ..image::PngLimits::default()
    };
    let error = image::vp8::lossy_info(&fixture("photo_lossy_q75.webp"), &limits)
        .expect_err("dimension cap");
    assert!(
        matches!(error, ImageError::LimitExceeded { .. }),
        "{error:?}"
    );
    // The pixel decoder enforces the same caps (before allocating the RGBA buffer).
    let error = image::decode_with_limits(&fixture("photo_lossy_q75.webp"), &limits)
        .expect_err("decode dimension cap");
    assert!(
        matches!(error, ImageError::LimitExceeded { .. }),
        "{error:?}"
    );
}

#[test]
fn corrupt_lossy_webp_is_a_typed_error() {
    let bytes = fixture("photo_lossy_q75.webp");
    // Container/header prefixes are rejected by the header parser.
    for length in [0, 4, 12, 20] {
        let error = image::vp8::lossy_info(
            &bytes[..length.min(bytes.len())],
            &image::PngLimits::default(),
        )
        .expect_err("truncated lossy");
        assert!(
            matches!(
                error,
                ImageError::Truncated { .. }
                    | ImageError::InvalidData { .. }
                    | ImageError::InvalidSignature
            ),
            "length {length}: {error:?}"
        );
    }
    // Truncated VP8 payloads (container intact, partitions cut) must also fail with a
    // typed error from `decode`, never panic or return random pixels.
    for fraction in [2usize, 4, 8, 16] {
        let length = bytes.len() / fraction;
        if length == 0 || length >= bytes.len() {
            continue;
        }
        let error = decode(&bytes[..length]).expect_err("truncated VP8 payload");
        assert!(
            matches!(
                error,
                ImageError::Truncated { .. }
                    | ImageError::InvalidData { .. }
                    | ImageError::InvalidSignature
                    | ImageError::LimitExceeded { .. }
            ),
            "length {length}: {error:?}"
        );
    }
}

#[test]
fn decodes_1024x768_lossy_within_time_budget() {
    // A/B note: this replaces the header-only timing check of the previous phase. The
    // full 1024x768 VP8 keyframe decode (3072 macroblocks) runs in a few tens of ms in
    // release; the bound is deliberately loose for debug/CI machines.
    use std::time::Instant;
    let bytes = fixture("photo_1024x768_lossy.webp");
    let start = Instant::now();
    let image = decode(&bytes).expect("1024x768 lossy");
    let elapsed = start.elapsed();
    assert_eq!(image.dimensions(), (1024, 768));
    eprintln!(
        "VP8 lossy 1024x768 decode: {:.2} ms",
        elapsed.as_secs_f64() * 1e3
    );
    assert!(elapsed.as_secs() < 5, "decode too slow: {elapsed:?}");
}

#[test]
fn vp8x_extended_containers_are_unsupported() {
    // VP8X adds a canvas, alpha and animation: decoding only the inner VP8/VP8L chunk
    // would silently drop them, so the extended container is a typed unsupported error
    // (never wrong pixels).
    let plain = fixture("photo_lossy_q75.webp");
    let vp8 = vp8_payload(&plain);
    let mut vp8x = [0u8; 10];
    vp8x[4] = 63; // canvas width - 1 = 64
    vp8x[7] = 47; // canvas height - 1 = 48
    for extra in [None, Some(*b"ALPH"), Some(*b"ANIM")] {
        let mut chunks: Vec<(&[u8; 4], &[u8])> = vec![(b"VP8X", &vp8x)];
        if let Some(id) = extra.as_ref() {
            chunks.push((id, &[0u8; 4]));
        }
        chunks.push((b"VP8 ", vp8));
        let bytes = riff_container(&chunks);
        let error = decode(&bytes).expect_err("VP8X must be rejected");
        assert!(
            matches!(error, ImageError::UnsupportedFeature { .. }),
            "{extra:?}: {error:?}"
        );
    }
}

/// Extracts the `VP8 ` chunk payload from a RIFF/WEBP container.
fn vp8_payload(bytes: &[u8]) -> &[u8] {
    let mut offset = 12usize;
    while offset + 8 <= bytes.len() {
        let length = u32::from_le_bytes([
            bytes[offset + 4],
            bytes[offset + 5],
            bytes[offset + 6],
            bytes[offset + 7],
        ]) as usize;
        let start = offset + 8;
        if &bytes[offset..offset + 4] == b"VP8 " {
            return &bytes[start..start + length];
        }
        offset = start + length + (length & 1);
    }
    panic!("fixture has no VP8 chunk");
}

/// Builds a RIFF/WEBP container around `(chunk id, payload)` pairs.
fn riff_container(chunks: &[(&[u8; 4], &[u8])]) -> Vec<u8> {
    let mut body = Vec::from(*b"WEBP");
    for (id, payload) in chunks {
        body.extend_from_slice(*id);
        body.extend_from_slice(&(payload.len() as u32).to_le_bytes());
        body.extend_from_slice(payload);
        if payload.len() % 2 == 1 {
            body.push(0);
        }
    }
    let mut bytes = Vec::from(*b"RIFF");
    bytes.extend_from_slice(&(body.len() as u32).to_le_bytes());
    bytes.extend_from_slice(&body);
    bytes
}

/// Compares two RGBA8 buffers (alpha ignored) and returns (max, mean) absolute error
/// over the RGB channels.
fn compare_rgba(decoded: &[u8], oracle: &[u8]) -> (i32, f64) {
    assert_eq!(decoded.len(), oracle.len());
    let mut max = 0i32;
    let mut sum = 0i64;
    for (ours, theirs) in decoded
        .as_chunks::<4>()
        .0
        .iter()
        .zip(oracle.as_chunks::<4>().0.iter())
    {
        for channel in 0..3 {
            let delta = (i32::from(ours[channel]) - i32::from(theirs[channel])).abs();
            max = max.max(delta);
            sum += i64::from(delta);
        }
    }
    let count = (decoded.len() / 4 * 3) as f64;
    (max, sum as f64 / count)
}
